import dataProvider from "@refinedev/simple-rest";
import "@refinedev/antd/dist/reset.css";

import { API_URL, VeloIQPortalApp, httpClient } from "@juicemantics/veloiq-ui";
import type { NavConfig } from "@juicemantics/veloiq-ui";
// Regenerated by `veloiq generate`: the models this portal's roles can read.
import { portalModuleRegistrations } from "./portalModels.gen";
// The portal's menu: created by `veloiq generate` once, then yours to edit.
import portalNavigationConfig from "./navigation.{{site}}.config.json";
// The portal's own pages and its replacements for standard pages.
import { portalPageOverrides, portalPageRoutes } from "./portalPages";

const portalDataProvider = dataProvider(API_URL, httpClient);

/** The {{site}} portal: the standard portal shell with this site's models, menu and pages. */
export default function App() {
    return (
        <VeloIQPortalApp
            site="{{site}}"
            dataProvider={portalDataProvider}
            moduleRegistrations={portalModuleRegistrations}
            navConfig={portalNavigationConfig as NavConfig}
            pageRoutes={portalPageRoutes}
            pageOverrides={portalPageOverrides}
        />
    );
}
